@import "@fontsource-variable/hanken-grotesk/wght.css";
@import "@fontsource-variable/hanken-grotesk/wght-italic.css";

/* Light (faithful): a warm stone page, white cards, warm ink and greys. Forest green is the
   brand (headings, outline buttons, links, the pricing gate, the active step, the footer),
   lime fills every CTA with forest text on it, burnt orange is kept for tape labels,
   hand-drawn underlines and the progress rail. */
:root {
  --background: #f0eeeb;
  --foreground: #292826;
  --card: #ffffff;
  --card-foreground: #292826;
  --popover: #ffffff;
  --popover-foreground: #292826;
  --primary: #1e4d2b;
  --primary-foreground: #ffffff;
  --secondary: #e4e2de;
  --secondary-foreground: #292826;
  --muted: #d8d7d5;
  --muted-foreground: #54524f;
  --accent: #b2dd79;
  --accent-foreground: #1e4d2b;
  --destructive: #c51808;
  --destructive-foreground: #ffffff;
  --border: #d8d7d5;
  --input: #d8d7d5;
  --ring: #77a45a;
  --highlight: #ed6c30;
  --highlight-foreground: #ffffff;
  --glow: #b2dd79;
  --chart-1: #1e4d2b;
  --chart-2: #77a45a;
  --chart-3: #ed6c30;
  --chart-4: #f7c33c;
  --chart-5: #048ee5;
  --sidebar: #ffffff;
  --sidebar-foreground: #292826;
  --sidebar-primary: #1e4d2b;
  --sidebar-primary-foreground: #ffffff;
  --sidebar-accent: #f0eeeb;
  --sidebar-accent-foreground: #292826;
  --sidebar-border: #d8d7d5;
  --sidebar-ring: #77a45a;

  --typeface-body: "Hanken Grotesk Variable", ui-sans-serif, system-ui, sans-serif;
  --typeface-display: "Hanken Grotesk Variable", ui-sans-serif, system-ui, sans-serif;
  --typeface-mono: ui-monospace, SFMono-Regular, Menlo, Consolas, monospace;
  --radius: 0.5rem;
  --page-width: 90rem;
  --page-gutter: clamp(1rem, 2.25vw, 2rem);
  --section-y: clamp(4rem, 7vw, 6rem);
}

/* Dark: the photo bands' night side as a whole page. Near-black warm stone, warm off-white
   ink, a lifted charcoal for cards, a mid forest green for surfaces with dark ink, lime kept
   for the CTAs, orange unchanged. */
.dark {
  --background: #171615;
  --foreground: #f0eeeb;
  --card: #24231f;
  --card-foreground: #f0eeeb;
  --popover: #24231f;
  --popover-foreground: #f0eeeb;
  --primary: #8fbf6a;
  --primary-foreground: #102a17;
  --secondary: #2e2d2a;
  --secondary-foreground: #f0eeeb;
  --muted: #2e2d2a;
  --muted-foreground: #a9a8a7;
  --accent: #b2dd79;
  --accent-foreground: #102a17;
  --destructive: #ff948a;
  --destructive-foreground: #102a17;
  --border: #ffffff26;
  --input: #ffffff33;
  --ring: #b2dd79;
  --highlight: #f09064;
  --highlight-foreground: #171615;
  --glow: #b2dd79;
  --chart-1: #b2dd79;
  --chart-2: #77a45a;
  --chart-3: #f09064;
  --chart-4: #f7c33c;
  --chart-5: #68baed;
  --sidebar: #24231f;
  --sidebar-foreground: #f0eeeb;
  --sidebar-primary: #8fbf6a;
  --sidebar-primary-foreground: #102a17;
  --sidebar-accent: #2e2d2a;
  --sidebar-accent-foreground: #f0eeeb;
  --sidebar-border: #ffffff26;
  --sidebar-ring: #b2dd79;
}
